#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static void emit(double v){uint64_t bits;memcpy(&bits,&v,sizeof(bits));printf("%016llx",(unsigned long long)bits);}
int main(void){char line[512],*next;while(fgets(line,sizeof(line),stdin)){double x=strtod(line,&next),y=strtod(next,NULL);emit(x);putchar(' ');emit(y);putchar(' ');emit(pow(x,y));putchar('\n');}return 0;}
